mapper.select:
SELECT B.BUSI_ID id, NVL(C.FINPROD_NAME, B.BUSI_ID) text FROM BOK_BOOKDETAIL_CURRENT A LEFT JOIN BOK_DETAIL_ID B ON A.BOOKSET_ID = B.BOOKSET_ID AND A.BUSI_ID = B.BUSI_ID LEFT JOIN FIN_PRODUCT C ON B.BUSI_ID = C.FINPROD_ID AND B.BUSI_DETAIL_TYPE = C.FINPROD_TYPE WHERE
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/
A.BASE_SUBJECT_NATURE IN ('QTYSK_QT')
A.BASE_SUBJECT_NATURE IN ('QTYSK_BJ', 'QTYSK_LX')
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/
AND A.BOOKSET_ID = #{bookSetId}
AND (B.BUSI_ID like '%' || #{search} || '%' OR C.FINPROD_NAME like '%' || #{search} || '%')
GROUP BY B.BUSI_ID, B.BUSI_DETAIL_TYPE, C.FINPROD_NAME ORDER BY B.BUSI_DETAIL_TYPE, B.BUSI_ID

WITH BASE_CURRENT AS ( SELECT A.* FROM ( SELECT A.BOOKSET_ID, A.BUSI_ID, A.BRANCH, A.BOOK_DATE, A.BOK_DETAIL_ID, A.BASE_SUBJECT_NATURE, A.O_AMT_HAPPEN_DATE, row_number() over (PARTITION BY A.BOOKSET_ID,A.BOK_DETAIL_ID,A.BASE_SUBJECT_NATURE,A.SUBJECT_NO, A.BRANCH ORDER BY A.BOOK_ORDER desc) as newResult FROM BOK_BOOKDETAIL_CURRENT A WHERE /**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/
A.BASE_SUBJECT_NATURE IN ('QTYSK_QT')
A.BASE_SUBJECT_NATURE IN ('QTYSK_BJ', 'QTYSK_LX')
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/ AND A.BOOK_DATE <= to_date(#{bookDate},'yyyy-MM-dd') /**账务日期**/
AND A.BASE_SUBJECT_NATURE = #{receivablesType}
AND A.BOOKSET_ID = #{bookSetId}
AND A.BUSI_ID in
#{bdFinprodId}
) A WHERE A.newResult=1 AND A.O_AMT_HAPPEN_DATE != 0 ) ,BASE2_CURRENT AS ( SELECT A.BOOKSET_ID, A.BUSI_ID AS FINPROD_ID, B.BUSI_DETAIL_TYPE AS FINPROD_TYPE, A.BRANCH, A.BASE_SUBJECT_NATURE, /**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/
SUM(CASE WHEN A.BASE_SUBJECT_NATURE ='QTYSK_QT' THEN A.O_AMT_HAPPEN_DATE ELSE 0 END) AS PRINAMT, SUM(CASE WHEN A.BASE_SUBJECT_NATURE ='QTYSK_LX' THEN A.O_AMT_HAPPEN_DATE ELSE 0 END) AS INTAMT
SUM(CASE WHEN A.BASE_SUBJECT_NATURE ='QTYSK_BJ' THEN A.O_AMT_HAPPEN_DATE ELSE 0 END) AS PRINAMT, SUM(CASE WHEN A.BASE_SUBJECT_NATURE ='QTYSK_LX' THEN A.O_AMT_HAPPEN_DATE ELSE 0 END) AS INTAMT
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/
FROM BASE_CURRENT A,BOK_DETAIL_ID B WHERE A.BOOKSET_ID = B.BOOKSET_ID AND A.BOK_DETAIL_ID = B.BOK_DETAIL_ID
AND A.BASE_SUBJECT_NATURE = #{receivablesType}
AND A.BOOKSET_ID = #{bookSetId}
AND A.BUSI_ID in
#{bdFinprodId}
GROUP BY A.BOOKSET_ID, A.BUSI_ID,B.BUSI_DETAIL_TYPE,A.BRANCH, A.BASE_SUBJECT_NATURE ) ,CALC AS ( SELECT DISTINCT R.FINPROD_ID,R.FINPROD_TYPE, DECODE(R.CALC_TYPE,'01','固定利率','02','浮动利率') AS CALC_TYPE, ROUND(R.YIELD*100,4) YIELD,R.BASIS FROM FIN_CASH_CALC_RULE R,( SELECT G.CASH_ID,F.FINPROD_ID,F.FINPROD_TYPE,MAX(F.EFF_DATE) EFF_DATE FROM FIN_CASH_CALC_RULE F,FIN_CASH_INFO G WHERE F.FINPROD_ID = G.FINPROD_ID AND F.FINPROD_TYPE = G.FINPROD_TYPE AND G.CASH_TYPE_1 ='02' GROUP BY G.CASH_ID,F.FINPROD_ID,F.FINPROD_TYPE ) H WHERE R.CASH_ID = H.CASH_ID AND R.FINPROD_ID = H.FINPROD_ID AND R.FINPROD_TYPE = H.FINPROD_TYPE AND R.EFF_DATE = H.EFF_DATE ) SELECT A.BOOKSET_ID bookSetId,/**账套代码**/ DECODE(A.BASE_SUBJECT_NATURE,'QTYSK_BJ','其他应收款-本金','QTYSK_LX','其他应收款-利息') AS receivablesType, A.FINPROD_ID AS bdFinprodId, /**标的资产代码**/ B.FINPROD_NAME AS bdFinprodName ,/**标的资产名称**/ A.prinamt, A.intamt, /**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/
CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN TO_CHAR(D.VDATE,'yyyy-MM-dd') ELSE NULL END vdate, /**计息开始日**/ CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN TO_CHAR(D.MDATE,'yyyy-MM-dd') ELSE NULL END mdate, /**计息截止日**/ CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_QT' THEN TO_CHAR(D.MDATE,'yyyy-MM-dd') ELSE NULL END tradeDate,/**还本日**/
CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN TO_CHAR(D.VDATE,'yyyy-MM-dd') ELSE NULL END vdate, /**计息开始日**/ CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_LX' THEN TO_CHAR(D.MDATE,'yyyy-MM-dd') ELSE NULL END mdate, /**计息截止日**/ CASE WHEN A.BASE_SUBJECT_NATURE = 'QTYSK_BJ' THEN TO_CHAR(D.MDATE,'yyyy-MM-dd') ELSE NULL END tradeDate,/**还本日**/
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/
CALC.BASIS basis,/**计息基础**/ CALC.CALC_TYPE calcType,/**利率类型**/ CALC.YIELD yield /**最新利率(%)**/ FROM BASE2_CURRENT A LEFT JOIN CALC ON A.FINPROD_ID = CALC.FINPROD_ID AND A.FINPROD_TYPE = CALC.FINPROD_TYPE LEFT JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_TYPE = B.FINPROD_TYPE LEFT JOIN FIN_TRADE_PRODUCT D ON A.FINPROD_ID = D.FINPROD_ID AND A.FINPROD_TYPE = D.FINPROD_TYPE AND A.BRANCH = D.BRANCH WHERE /**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/
A.BASE_SUBJECT_NATURE IN ('QTYSK_QT')
A.BASE_SUBJECT_NATURE IN ('QTYSK_BJ','QTYSK_LX')
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/
AND D.MDATE >= to_date(#{vdate},'yyyy-MM-dd')
AND D.MDATE <=to_date(#{mdate},'yyyy-MM-dd')
ORDER BY A.BOOKSET_ID,A.FINPROD_TYPE,A.FINPROD_ID,A.BASE_SUBJECT_NATURE
